import itertools,json
jobs='ABCDE'
cost=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
t=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def nominal(p):
 return sum(cost[j][i] for i,j in enumerate(p))+sum(t[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>=pos['D']: return False
 return {'rain':pos['E']!=2 and pos['D']!=5,'road':pos['B']!=5 and pos['D']!=1,'lift':pos['D']!=4 and pos['C']!=1}[s]
def penalty(p,s):
 j,threshold,rate={'rain':('A',2,6),'road':('C',3,8),'lift':('E',1,5)}[s]
 return rate*max(0,p.index(j)+1-threshold)
results=[]
for p0 in itertools.permutations(jobs):
 p=''.join(p0)
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i]
  neighbors.append((''.join(q),4))
 repairs={};rc={}
 for s in ['rain','road','lift']:
  opts=[(nominal(q)+penalty(q,s)+fee,q) for q,fee in neighbors if legal(q,s)]
  if not opts:break
  rc[s],repairs[s]=min(opts)
 if len(rc)==3:results.append((nominal(p)+max(rc.values()),p,repairs,rc))
results.sort()
best=results[0]
print(json.dumps(dict(roster=best[1],score=best[0],repairs=best[2],repair_costs=best[3],feasible_count=len(results),next_score=min(r[0] for r in results if r[0]>best[0]))))
print('Optimal publications:',[(r[1],r[0]) for r in results if r[0]==best[0]])
print('Published nominal:',nominal(best[1]))
for s,q in best[2].items():print(s,q,'nominal',nominal(q),'penalty',penalty(q,s),'swap',q!=best[1])

